theorem isUnit_mulChar_apply_unit_pow_eq_one {η : MulChar (𝓞 L ⧸ P) (𝓞 L)} {r : ℕ}
    (v : (𝓞 L ⧸ P)ˣ) (hη : η ^ r = 1) :
