theorem isUnit_span_gaussSum_of_eq_one {ω : MulChar F (𝓞 L)} {ψ : AddChar F (𝓞 L)}
    (hψ : ψ ≠ 1) {a : ℕ} (ha : ω ^ a = 1) :
    IsUnit (Ideal.span {gaussSum (ω ^ a) ψ})

theorem gaussValuation_ne_top {P : Ideal (𝓞 L)} (hP : Prime P) {ω : MulChar F (𝓞 L)}
    {ψ : AddChar F (𝓞 L)} {a : ℕ} (hne : gaussSum (ω ^ a) ψ ≠ 0) :
    gaussValuation P ω ψ a ≠ ⊤

theorem gaussValuation_add_le {P : Ideal (𝓞 L)} (hP : Prime P) {ω : MulChar F (𝓞 L)}
    {ψ : AddChar F (𝓞 L)} (hψ : ψ ≠ 1) (a b : ℕ) :
    gaussValuation P ω ψ (a + b) ≤ gaussValuation P ω ψ a + gaussValuation P ω ψ b

theorem gaussSum_sub_linear_mem {ω : MulChar F (𝓞 L)} {ψ : AddChar F (𝓞 L)} {π : 𝓞 L}
    {e : F → ℕ} (hψ : ∀ a, ψ a = (1 + π) ^ e a) :
    gaussSum ω ψ - (∑ a, ω a + π * ∑ a, ω a * (e a : 𝓞 L)) ∈ Ideal.span {π ^ 2}
